const note = (text) => ({ type: 'stack', id: 'root', gap: 'small', children: [{ type: 'text', id: 't', text }, { type: 'button', id: 'move', label: 'Move to the next place', variant: 'secondary' }] });
const places = ['side', 'floating', 'sidebar', 'panel'];
let at = 0;
async function next() {
  at = (at + 1) % places.length;
  await sdk.ui.place('notes', { placement: places[at], ...(places[at] === 'floating' ? { size: { width: 360, height: 220 }, position: 'center' } : {}) });
  await sdk.ui.update('notes', note('Now in: ' + places[at]));
  if (places[at] === 'panel' || places[at] === 'sidebar') await sdk.ui.open('notes');
}
await sdk.ui.registerPanel({ id: 'notes', title: 'Notes', placement: 'side', size: { width: 320 }, view: note('Now in: side') }, async (e) => { if (e.type === 'action' && e.id === 'move') await next(); });
await sdk.ui.registerPanel({ id: 'clock', title: 'Clock', placement: 'floating', size: { width: 240, height: 140 }, position: 'bottom-right', view: { type: 'stat', id: 's', label: 'Started', value: new Date().toLocaleTimeString() } }, async () => {});
await sdk.ui.registerPanel({ id: 'shelf', title: 'Shelf', placement: 'sidebar', view: { type: 'text', id: 't', text: 'A section at the bottom of the sidebar.' } }, async () => {});
await sdk.commands.register({ name: 'layout', description: 'Move the notes panel to the next place' }, () => next());
await sdk.commands.register({ name: 'tidy', description: 'Put up to four open chats in a grid' }, async () => {
  const ids = (await sdk.panes.list({ all: true })).filter((p) => p.kind === 'session').slice(0, 4).map((p) => p.id);
  if (ids.length < 2) return;
  const pane = (id) => ({ type: 'pane', id });
  const row = (a, b) => (b ? { type: 'split', dir: 'row', a: pane(a), b: pane(b) } : pane(a));
  const layout = ids.length > 2 ? { type: 'split', dir: 'col', a: row(ids[0], ids[1]), b: row(ids[2], ids[3]) } : row(ids[0], ids[1]);
  const { id } = await sdk.panes.createGroup(layout, 'Tidy');
  await sdk.panes.openGroup(id);
  await sdk.workspace.sidebar({ collapsed: true });
});
